pub fn shaderAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "aPos")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "aColor")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "aTexCoord")) {
        return 2;
    }
    return null;
}
pub fn shaderTextureSlot(tex_name: []const u8) ?usize {
    if (std.mem.eql(u8, tex_name, "tex0")) {
        return 0;
    }
    if (std.mem.eql(u8, tex_name, "tex1")) {
        return 1;
    }
    return null;
}
pub fn shaderSamplerSlot(smp_name: []const u8) ?usize {
    if (std.mem.eql(u8, smp_name, "smp")) {
        return 0;
    }
    return null;
}
